glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);

  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;

  gl_Position = pos;
}

glsl3.frag:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform sampler2D noiseTex;
uniform sampler2D maskTex;

uniform PROPERTIES {
  float noiseIntensity;
  float noiseSpeedX;
  float noiseSpeedY;
  float time;
  float rate;
};

float random (in vec2 st) { 
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123); 
}

vec2 getOffsetFromNoiseTex(vec2 uv) {
  float x = fract(uv.x);
  float y = fract(uv.y);
  vec4 color = texture2D(noiseTex, vec2(x, y));
  color = (color * 2.0 - 1.0) * 0.1;
  return color.xy;
}

void main () {
  vec4 o = vec4(1, 1, 1, 1);

  #if USE_TEXTURE

  vec4 mask = texture2D(maskTex, v_uv0);
  float t = (cc_time.x + time) * rate;
  vec2 timer = vec2(t * noiseSpeedX, t * noiseSpeedY);
  vec2 offset = getOffsetFromNoiseTex(v_uv0 + timer);
  o *= texture2D(texture, v_uv0 + offset * noiseIntensity * mask.r);
  #endif

  o *= v_color;

  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

